const $=s=>document.querySelector(s);const data=[{type:'policy',mineral:'锂',title:'澳洲关键矿产战略：锂产业链与出口支持措施',source:'澳洲 DISR',date:'2026-10-14',text:'演示文档：展示政策发布机构、适用矿种及政策变化的结构化摘要。',url:'https://www.industry.gov.au/'},{type:'news',mineral:'铜',title:'全球铜矿供应与需求：市场关注新增产能进展',source:'MINING.COM',date:'2026-10-14',text:'演示文档：汇总铜矿项目、供应预期及市场关注点。',url:'https://www.mining.com/'},{type:'policy',mineral:'稀土',title:'稀土产业发展动态：资源利用与产业链协同',source:'中国稀土集团',date:'2026-10-13',text:'演示文档：展示稀土政策及产业动态的采集和分类效果。',url:null},{type:'news',mineral:'铁矿石',title:'铁矿石市场观察：港口库存与钢厂采购需求',source:'S&P Global',date:'2026-10-13',text:'演示文档：记录市场新闻的来源、发布日期和矿种标签。',url:'https://www.spglobal.com/'}];let filter='all',view='overview';let endpoint=localStorage.getItem('mineral-query-endpoint')||'';function esc(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function items(){return data.filter(d=>(filter==='all'||d.type===filter)&&($('#mineral').value==='all'||d.mineral===$('#mineral').value))}function render(){ $('#feed').innerHTML=items().map(d=>`<article class="item" tabindex="0" data-id="${data.indexOf(d)}"><div class="meta"><span class="tag ${d.type}">${d.type==='policy'?'矿产政策':'矿业新闻'}</span><span>${d.source}</span><span style="margin-left:auto">${d.date}</span></div><h3>${d.title}</h3><small>${d.mineral}　 /　示例文档　 ↗</small></article>`).join('')||'<p>没有符合筛选条件的示例文档。</p>';}render();document.addEventListener('click',e=>{const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('selected',b===f));render()}const it=e.target.closest('[data-id]');if(it)showDoc(Number(it.dataset.id));const nav=e.target.closest('[data-view]');if(nav)navigate(nav.dataset.view)});$('#mineral').onchange=render;$('#feed').onkeydown=e=>{if(e.key==='Enter'&&e.target.dataset.id)showDoc(Number(e.target.dataset.id))};function showDoc(i){const d=data[i];$('#title').textContent='情报详情';$('#subtitle').textContent='示例内容 · 用于展示文档阅读与来源追溯';$('#overview').hidden=true;$('#detail').hidden=false;$('#detail').innerHTML=`<div class="panel"><span class="tag ${d.type}">${d.mineral} · 示例</span><h1>${d.title}</h1><p>${d.source}　|　${d.date}</p><p>${d.text}</p><p>这不是经过采集验证的真实新闻或政策，不能作为研究结论的依据。</p>${d.url?`<a href="${d.url}" target="_blank" rel="noopener">访问来源首页 ↗</a>`:'<p>演示记录未配置来源链接。</p>'}</div>`}const labels={overview:'情报总览',news:'矿业新闻',policy:'关键矿产政策',prices:'市场价格',ask:'智能问答',pipeline:'数据管线',eval:'质量评估'};function navigate(v){view=v;$('#breadcrumb').textContent=labels[v];$('#title').textContent=labels[v];document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#subtitle').textContent=v==='overview'?'连接新闻、政策与价格，让每一次判断都有据可循。':'演示工作空间 · 接入真实服务后可展示生产数据';$('#overview').hidden=!['overview','ask'].includes(v);$('#detail').hidden=['overview','ask'].includes(v);if(v==='ask')$('#query').focus();if(v==='news'||v==='policy'){$('#detail').innerHTML='<section class="panel">'+data.filter(d=>d.type===v).map(d=>`<article class="item" data-id="${data.indexOf(d)}"><div class="meta">${d.source} · ${d.date} · 示例</div><h3>${d.title}</h3><p>${d.text}</p></article>`).join('')+'</section>'}if(v==='prices')$('#detail').innerHTML='<section class="panel"><h2>市场价格 · 示例</h2><p>所有价格均为界面演示数值，未接入行情授权服务。</p><table><tr><th>品种</th><th>市场 / 口径</th><th>价格</th><th>单位</th></tr>'+Object.entries(prices).map(([k,p])=>`<tr><td>${k}</td><td>${p[0]}</td><td>${p[1]}</td><td>${p[3]}</td></tr>`).join('')+'</table></section>';if(v==='pipeline')$('#detail').innerHTML='<section class="panel"><h2>采集 → 清洗 → 去重 → 向量化 → 入库</h2><p>当前为前端演示。采集作业未运行，648 条为示例统计。</p><table><tr><th>来源</th><th>采集要求</th><th>当前状态</th></tr><tr><td>新闻</td><td>RSS + 正文抽取</td><td>待接入</td></tr><tr><td>政策</td><td>发布机构 + 政策条款</td><td>待核实近30天文档量</td></tr><tr><td>价格</td><td>品种、日期、数值、单位</td><td>待授权并确认锂价格市场</td></tr></table><p>建议主键：来源 + 规范化 URL；价格使用市场 + 品种 + 合约 + 时间 + 口径。内容哈希用于识别重复文档。</p></section>';if(v==='eval')$('#detail').innerHTML='<section class="panel"><h2>质量评估 · 示例报告</h2><p>下列指标是页面演示值，尚未执行真实检索与问答评估。</p><table><tr><th>指标</th><th>示例结果</th><th>评估方式</th></tr><tr><td>Recall@5</td><td>85.0%</td><td>检查前5个结果对标注证据的覆盖</td></tr><tr><td>回答忠实度</td><td>92.5%</td><td>逐项检查回答是否得到证据支持</td></tr><tr><td>标准问答</td><td>20 条（规划）</td><td>接入数据后人工核验并冻结基准</td></tr></table></section>'}const prices={'铜':['LME 铜','9,842.50','+1.24%','USD / 吨'],'锌':['LME 锌','2,945.00','+0.62%','USD / 吨'],'镍':['LME 镍','16,730.00','+0.85%','USD / 吨'],'锂':['锂价格 · 市场待确认','78,500.00','+2.10%','CNY / 吨'],'铁矿石':['上海钢联铁矿石 · 示例','785.00','+0.38%','CNY / 吨']};document.querySelectorAll('[data-metal]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-metal]').forEach(t=>t.classList.toggle('selected',t===b));const p=prices[b.dataset.metal];$('#marketname').textContent=p[0]+' · '+p[3];$('#price').textContent=p[1];$('#change').textContent=p[2]+' ↗';const idx=Object.keys(prices).indexOf(b.dataset.metal);const points=Array.from({length:18},(_,i)=>`${Math.round(i*420/17)} ${Math.round(138-i*6+Math.sin(i*1.7+idx)*15)}`);const path='M'+points.join('L');$('#line').setAttribute('d',path);$('#area').setAttribute('d',path+'V175H0Z')});document.querySelectorAll('.suggestions button').forEach(b=>b.onclick=()=>{$('#query').value=b.textContent;$('#query').focus()});$('#queryform').onsubmit=async e=>{e.preventDefault();const q=$('#query').value.trim();if(!q){$('#query').focus();return}const out=$('#answer');out.hidden=false;if(!endpoint){out.textContent='演示回答\n\n当前未连接真实检索服务，无法判断“'+q+'”的实际结论。\n\n正式接入后，系统会按时间、国家和矿种筛选新闻、政策与价格，并返回有来源链接的回答。\n\n可用示例证据：'+data.filter(d=>q.includes(d.mineral)).map(d=>d.title+'（'+d.source+'，示例）').join('；');return}out.textContent='正在检索…';const submit=e.target.querySelector('button');submit.disabled=true;const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);try{const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q}),signal:controller.signal});if(!r.ok)throw Error('服务返回 '+r.status);const result=await r.json();if(typeof result.answer!=='string')throw Error('响应中缺少 answer 字段');out.textContent=result.answer}catch(err){out.textContent='请求失败：'+(err.name==='AbortError'?'请求超时':err.message)+'。请检查服务地址与跨域设置。'}finally{clearTimeout(timeout);submit.disabled=false}};$('#settings').onclick=()=>{$('#endpoint').value=endpoint;$('#config').showModal()};$('#closeconfig').onclick=()=>$('#config').close();$('#saveconfig').onclick=()=>{const value=$('#endpoint').value.trim();if(value){try{const u=new URL(value);if(!['https:','http:'].includes(u.protocol))throw Error()}catch{$('#endpoint').setCustomValidity('请输入有效的 HTTP 或 HTTPS 地址');$('#endpoint').reportValidity();return}}$('#endpoint').setCustomValidity('');endpoint=value;localStorage.setItem('mineral-query-endpoint',value);$('#config').close()};$('#endpoint').oninput=()=>$('#endpoint').setCustomValidity('');$('#allnews').onclick=()=>navigate('news');$('#pipelinebtn').onclick=()=>navigate('pipeline');$('#export').onclick=()=>{const blob=new Blob(['\ufeff'+['类型,矿种,标题,来源,日期,数据性质',...items().map(d=>[d.type,d.mineral,d.title,d.source,d.date,'示例数据'].map(x=>'"'+String(x).replaceAll('"','""')+'"').join(','))].join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='矿观-示例情报.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
